wwv_flow_imp_page.create_page_validation(
 p_id=>wwv_flow_imp.id(15332148804317909)
,p_tabular_form_region_id=>wwv_flow_imp.id(15325630554301979)
,p_validation_name=>'CHECK_DUBLICATE_NAMES'
,p_static_id=>'new'
,p_validation_sequence=>10
,p_validation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
'',
'DECLARE',
'    v_dup_in_db     NUMBER := 0;',
'    v_dup_in_batch  NUMBER := 0;',
'BEGIN',
'    ',
'    SELECT COUNT(*)',
'      INTO v_dup_in_db',
'      FROM demo d',
'     WHERE upper(d.name) = upper(:NAME)',
'       AND NVL(d.id, -1) != NVL(:ID, -1);',
'',
'    IF v_dup_in_db > 0 THEN',
'        RETURN ''This name already exists in the database.'';',
'    END IF;',
'',
'   ',
'    SELECT COUNT(*)',
'      INTO v_dup_in_batch',
'      FROM apex_collections',
'     WHERE collection_name = ''MY_COLLECTION''',
'       AND UPPER(c001) = UPPER(:NAME);',
'',
'    IF v_dup_in_batch > 0 THEN',
'        RETURN ''Duplicate name entered in this same save. Please use unique names.'';',
'    END IF;',
'',
'    ',
'    apex_collection.add_member(',
'        p_collection_name => ''MY_COLLECTION'',',
'        p_c001            => :NAME',
'    );',
'',
'    RETURN NULL;',
'EXCEPTION',
'    WHEN OTHERS THEN',
'        RETURN ''Validation error: '' || SQLERRM;',
'END;'))
,p_validation2=>'PLSQL'
,p_validation_type=>'FUNC_BODY_RETURNING_ERR_TEXT'
,p_always_execute=>'Y'
,p_associated_column=>'NAME'
,p_error_display_location=>'INLINE_WITH_FIELD_AND_NOTIFICATION'
,p_required_patch=>wwv_flow_imp.id(15305950571286794)
);
